rawInput.command:
python3 <<'PY'
import json
from pathlib import Path

p = Path('.grok/hooks/entire.json')
data = json.loads(p.read_text())

ABS = "/Users/kevinbarnard/.local/bin/entire"
# Portable wrap matching Entire's "missing binary never breaks the session" contract.
def grok_cmd(hook_name: str) -> str:
    return (
        "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; "
        f"exec entire hooks grok {hook_name}'"
    )

cleaned = {"hooks": {}}
for event, entries in data["hooks"].items():
    new_entries = []
    for entry in entries:
        hooks = []
        for h in entry.get("hooks", []):
            cmd = h.get("command", "")
            if "hooks claude-code" in cmd:
                continue
            name = h.get("name", "")
            hook_name = None
            if name.startswith("entire-"):
                hook_name = name[len("entire-"):]
            elif "hooks grok " in cmd:
                # e.g. "... hooks grok session-start ..."
                after = cmd.split("hooks grok ", 1)[1]
                hook_name = after.split()[0]
            if not hook_name:
                continue
            new_h = {
                "type": "command",
                "command": grok_cmd(hook_name),
                "name": f"entire-{hook_name}",
                "timeout": h.get("timeout", 10000),
            }
            hooks.append(new_h)
        if not hooks:
            continue
        new_entry = {"hooks": hooks}
        if "matcher" in entry:
            new_entry["matcher"] = entry["matcher"]
        new_entries.append(new_entry)
    if new_entries:
        cleaned["hooks"][event] = new_entries

# stable key order: keep installer-ish alpha order
cleaned["hooks"] = dict(sorted(cleaned["hooks"].items()))

text = json.dumps(cleaned, indent=2) + "\n"
p.write_text(text)
print(text)
print('---')
print('claude-code leftovers', text.count('claude-code'))
print('hooks grok', text.count('hooks grok'))
print('absolute path', ABS in text)
PY

